/**
 * Sortable YYYY-MM-DD for `instant` as seen in `timeZone`.
 * The timezone is required on purpose: a default is how this bug returns.
 */
export function dayKey(instant: Date, timeZone: string): string {
  // en-CA renders year-month-day, which sorts lexicographically.
  return new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(instant)
}

export function groupByDay<T>(
  rows: readonly T[],
  at: (row: T) => Date,
  timeZone: string,
): Map<string, T[]> {
  const out = new Map<string, T[]>()
  for (const row of rows) {
    const key = dayKey(at(row), timeZone)
    const bucket = out.get(key)
    if (bucket) bucket.push(row)
    else out.set(key, [row])
  }
  return out
}

import { expect, test } from 'vitest'
import { dayKey } from './day-key'

// 23:30 on the 4th in Los Angeles is already the 5th in UTC.
const instant = new Date('2026-09-05T06:30:00.000Z')

test('day key follows the requested timezone, not UTC', () => {
  expect(dayKey(instant, 'America/Los_Angeles')).toBe('2026-09-04')
  expect(dayKey(instant, 'UTC')).toBe('2026-09-05')
})
